<?php

namespace App\Http\Controllers\Client;

use App\Http\Controllers\Controller;
use App\Models\LoyaltyCard;
use Illuminate\Http\JsonResponse;
use Illuminate\Http\RedirectResponse;
use Illuminate\Http\Request;
use Illuminate\View\View;
use SimpleSoftwareIO\QrCode\Facades\QrCode;

class ClientLoyaltyController extends Controller
{
    /**
     * Display a listing of loyalty cards generated by this client.
     */
    public function index(Request $request): View
    {
        $client = auth('client')->user();
        $settings = $client->getLoyaltyProgramSetting();

        $query = LoyaltyCard::where('client_id', $client->id)
            ->with(['transactions' => fn ($q) => $q->latest()->take(3)]);

        if ($request->filled('search')) {
            $search = trim($request->search);
            $query->where(function ($q) use ($search) {
                $q->where('customer_name', 'like', "%{$search}%")
                    ->orWhere('card_code', 'like', "%{$search}%")
                    ->orWhere('customer_phone', 'like', "%{$search}%")
                    ->orWhere('customer_email', 'like', "%{$search}%")
                    ->orWhere('nfc_uid', 'like', "%{$search}%");
            });
        }

        if ($request->filled('type')) {
            $query->where('card_type', $request->type);
        }

        if ($request->filled('status')) {
            $query->where('status', $request->status);
        }

        $cards = $query->latest('last_activity_at')->latest('id')->paginate(12)->withQueryString();

        // Quota calculations
        $totalCards = $client->loyaltyCards()->count();
        $cardLimit = (int) ($client->loyalty_card_limit ?? 20);
        $remainingQuota = max(0, $cardLimit - $totalCards);
        $usagePercent = $cardLimit > 0 ? min(100.0, round(($totalCards / $cardLimit) * 100, 1)) : 100.0;
        $canGenerate = $client->canGenerateLoyaltyCard();

        // Performance metrics
        $totalStampsIssued = (int) $client->loyaltyCards()->sum('total_stamps_earned');
        $totalRewardsRedeemed = (int) $client->loyaltyCards()->sum('rewards_redeemed_count');
        $totalPointsBalance = (int) $client->loyaltyCards()->sum('points_balance');
        $activeMembersCount = $client->loyaltyCards()->where('status', 'active')->count();

        return view('client.loyalty.index', compact(
            'client',
            'cards',
            'settings',
            'totalCards',
            'cardLimit',
            'remainingQuota',
            'usagePercent',
            'canGenerate',
            'totalStampsIssued',
            'totalRewardsRedeemed',
            'totalPointsBalance',
            'activeMembersCount'
        ));
    }

    /**
     * Show form to generate a new loyalty card.
     */
    public function create(): View|RedirectResponse
    {
        $client = auth('client')->user();

        if (! $client->canGenerateLoyaltyCard()) {
            return redirect()->route('client.loyalty.index')->with(
                'error',
                "Votre limite autorisée de cartes fidélité ({$client->loyalty_card_limit} cartes) a été atteinte. Veuillez contacter l'administrateur pour augmenter votre quota."
            );
        }

        $suggestedCode = LoyaltyCard::generateUniqueCardCode();
        $settings = $client->getLoyaltyProgramSetting();

        return view('client.loyalty.create', compact('client', 'suggestedCode', 'settings'));
    }

    /**
     * Store a newly created loyalty card, enforcing admin quota limits.
     */
    public function store(Request $request): RedirectResponse
    {
        $client = auth('client')->user();

        // Enforce quota authorization
        if (! $client->canGenerateLoyaltyCard()) {
            return redirect()->route('client.loyalty.index')->with(
                'error',
                "Impossible de créer une carte : quota maximal de cartes ({$client->loyalty_card_limit}) atteint. Contactez votre administrateur."
            );
        }

        $validated = $request->validate([
            'customer_name' => 'required|string|max:150',
            'customer_phone' => 'nullable|string|max:50',
            'customer_email' => 'nullable|email|max:150',
            'card_type' => 'required|in:both,qr_code,nfc',
            'nfc_uid' => 'nullable|string|max:100',
            'max_stamps' => 'required|integer|min:2|max:50',
            'reward_text' => 'required|string|max:255',
            'initial_stamps' => 'nullable|integer|min:0|max:50',
            'initial_points' => 'nullable|integer|min:0|max:100000',
            'notes' => 'nullable|string|max:1000',
        ]);

        $initialStamps = (int) ($validated['initial_stamps'] ?? 0);
        $initialPoints = (int) ($validated['initial_points'] ?? 0);
        $maxStamps = (int) $validated['max_stamps'];
        if ($initialStamps > $maxStamps) {
            $initialStamps = $maxStamps;
        }

        $card = $client->loyaltyCards()->create([
            'card_code' => LoyaltyCard::generateUniqueCardCode(),
            'customer_name' => $validated['customer_name'],
            'customer_phone' => $validated['customer_phone'] ?? null,
            'customer_email' => $validated['customer_email'] ?? null,
            'card_type' => $validated['card_type'],
            'nfc_uid' => ! empty($validated['nfc_uid']) ? trim($validated['nfc_uid']) : null,
            'stamps_count' => $initialStamps,
            'max_stamps' => $maxStamps,
            'reward_text' => $validated['reward_text'],
            'total_stamps_earned' => $initialStamps,
            'rewards_redeemed_count' => 0,
            'points_balance' => $initialPoints,
            'status' => 'active',
            'notes' => $validated['notes'] ?? null,
            'last_activity_at' => now(),
        ]);

        if ($initialStamps > 0) {
            $card->transactions()->create([
                'client_id' => $client->id,
                'action' => 'stamp_added',
                'stamps_delta' => $initialStamps,
                'points_delta' => 0,
                'notes' => "Tampons initiaux lors de l'adhésion",
                'created_at' => now(),
            ]);
        }

        if ($initialPoints > 0) {
            $card->transactions()->create([
                'client_id' => $client->id,
                'action' => 'points_earned',
                'stamps_delta' => 0,
                'points_delta' => $initialPoints,
                'notes' => "Points de bienvenue offerts à l'adhésion",
                'created_at' => now(),
            ]);
        }

        return redirect()->route('client.loyalty.show', $card)->with(
            'success',
            "Carte de fidélité émise avec succès pour {$card->customer_name} ! (Code : {$card->card_code})"
        );
    }

    /**
     * Show details of a loyalty card with interactive stamp puncher, points calculator and pass preview.
     */
    public function show(LoyaltyCard $loyalty): View
    {
        $this->authorizeClientAccess($loyalty);

        $client = auth('client')->user();
        $settings = $client->getLoyaltyProgramSetting();

        $loyalty->load(['transactions' => fn ($q) => $q->latest()->take(30)]);

        // Calculate monetary discount equivalent of current points balance
        $pointsDiscountValue = $settings->calculateDiscountForPoints($loyalty->points_balance);

        // Generate high quality QR code SVG pointing to public digital pass
        $qrSvg = (string) QrCode::format('svg')
            ->size(220)
            ->margin(1)
            ->color(87, 54, 233)
            ->generate($loyalty->public_url);

        return view('client.loyalty.show', compact('loyalty', 'qrSvg', 'settings', 'pointsDiscountValue'));
    }

    /**
     * Quick Punch: Add stamps to customer card.
     */
    public function stamp(Request $request, LoyaltyCard $loyalty): JsonResponse|RedirectResponse
    {
        $this->authorizeClientAccess($loyalty);

        $validated = $request->validate([
            'count' => 'nullable|integer|min:1|max:20',
            'notes' => 'nullable|string|max:255',
        ]);

        $count = (int) ($validated['count'] ?? 1);
        $loyalty->addStamp($count, $validated['notes'] ?? null);

        if ($request->wantsJson()) {
            return response()->json([
                'success' => true,
                'message' => "+{$count} tampon(s) attribué(s) !",
                'stamps_count' => $loyalty->stamps_count,
                'max_stamps' => $loyalty->max_stamps,
                'is_reward_available' => $loyalty->isRewardAvailable(),
                'progress_percentage' => $loyalty->progressPercentage(),
            ]);
        }

        return redirect()->back()->with(
            'success',
            "+{$count} tampon(s) attribué(s) à {$loyalty->customer_name} !"
        );
    }

    /**
     * Redeem reward when stamps threshold is reached.
     */
    public function redeem(Request $request, LoyaltyCard $loyalty): JsonResponse|RedirectResponse
    {
        $this->authorizeClientAccess($loyalty);

        if (! $loyalty->isRewardAvailable()) {
            if ($request->wantsJson()) {
                return response()->json([
                    'success' => false,
                    'message' => 'Nombre de tampons insuffisant pour débloquer la récompense.',
                ], 422);
            }

            return redirect()->back()->with('error', 'Nombre de tampons insuffisant pour réclamer cette récompense.');
        }

        $notes = $request->input('notes');
        $loyalty->redeemReward($notes);

        if ($request->wantsJson()) {
            return response()->json([
                'success' => true,
                'message' => "Récompense ({$loyalty->reward_text}) débloquée et réclamée !",
                'stamps_count' => $loyalty->stamps_count,
                'rewards_redeemed_count' => $loyalty->rewards_redeemed_count,
                'progress_percentage' => $loyalty->progressPercentage(),
            ]);
        }

        return redirect()->back()->with(
            'success',
            "Récompense '{$loyalty->reward_text}' accordée à {$loyalty->customer_name} !"
        );
    }

    /**
     * Adjust points directly from card management view (traditional form).
     */
    public function adjustCardPoints(Request $request, LoyaltyCard $loyalty): RedirectResponse
    {
        $this->authorizeClientAccess($loyalty);

        $validated = $request->validate([
            'action' => 'required|in:add,deduct',
            'points' => 'required|integer|min:1|max:100000',
            'notes' => 'nullable|string|max:255',
        ]);

        $points = (int) $validated['points'];
        $notes = $validated['notes'] ?? null;

        if ($validated['action'] === 'add') {
            $loyalty->addPoints($points, $notes);

            return redirect()->back()->with('success', "+{$points} points ajoutés au solde de {$loyalty->customer_name}.");
        }

        if ($loyalty->points_balance < $points) {
            return redirect()->back()->with('error', "Solde insuffisant : ce client n'a que {$loyalty->points_balance} points.");
        }

        $loyalty->deductPoints($points, $notes);

        return redirect()->back()->with('success', "-{$points} points déduits du solde de {$loyalty->customer_name}.");
    }

    /**
     * Update customer details or NFC UID on card.
     */
    public function update(Request $request, LoyaltyCard $loyalty): RedirectResponse
    {
        $this->authorizeClientAccess($loyalty);

        $validated = $request->validate([
            'customer_name' => 'required|string|max:150',
            'customer_phone' => 'nullable|string|max:50',
            'customer_email' => 'nullable|email|max:150',
            'card_type' => 'required|in:both,qr_code,nfc',
            'nfc_uid' => 'nullable|string|max:100',
            'reward_text' => 'required|string|max:255',
            'max_stamps' => 'required|integer|min:2|max:50',
            'status' => 'required|in:active,suspended',
            'notes' => 'nullable|string|max:1000',
        ]);

        $loyalty->update([
            'customer_name' => $validated['customer_name'],
            'customer_phone' => $validated['customer_phone'] ?? null,
            'customer_email' => $validated['customer_email'] ?? null,
            'card_type' => $validated['card_type'],
            'nfc_uid' => ! empty($validated['nfc_uid']) ? trim($validated['nfc_uid']) : null,
            'reward_text' => $validated['reward_text'],
            'max_stamps' => (int) $validated['max_stamps'],
            'status' => $validated['status'],
            'notes' => $validated['notes'] ?? null,
        ]);

        return redirect()->route('client.loyalty.show', $loyalty)->with('success', 'Informations de la carte mises à jour.');
    }

    /**
     * Delete loyalty card (frees up client quota).
     */
    public function destroy(LoyaltyCard $loyalty): RedirectResponse
    {
        $this->authorizeClientAccess($loyalty);

        $customer = $loyalty->customer_name;
        $loyalty->delete();

        return redirect()->route('client.loyalty.index')->with(
            'success',
            "Carte de fidélité pour {$customer} supprimée. Votre quota a été libéré (+1 disponible)."
        );
    }

    /**
     * Quick scanner / fast look-up interface for counter staff.
     */
    public function scan(Request $request): View|RedirectResponse
    {
        $client = auth('client')->user();

        if ($request->filled('query')) {
            $query = trim($request->query('query'));
            $card = $client->loyaltyCards()
                ->where(function ($q) use ($query) {
                    $q->where('card_code', $query)
                        ->orWhere('nfc_uid', $query)
                        ->orWhere('customer_phone', $query);
                })
                ->first();

            if ($card) {
                return redirect()->route('client.loyalty.show', $card)->with(
                    'success',
                    "Client identifié : {$card->customer_name}"
                );
            }

            return redirect()->route('client.loyalty.scan')->with(
                'error',
                "Aucune carte fidélité trouvée pour la recherche '{$query}'."
            );
        }

        return view('client.loyalty.scan', compact('client'));
    }

    /**
     * Dedicated POS Scanner Terminal with Live Camera & NFC Support.
     */
    public function terminal(Request $request): View
    {
        $client = auth('client')->user();
        $settings = $client->getLoyaltyProgramSetting();

        $initialCard = null;
        if ($request->filled('card_code')) {
            $initialCard = $client->loyaltyCards()->where('card_code', $request->card_code)->first();
        }

        return view('client.loyalty.terminal', compact('client', 'settings', 'initialCard'));
    }

    /**
     * AJAX Endpoint: Look up card by QR code, NFC UID, or Phone number.
     */
    public function lookupCard(Request $request): JsonResponse
    {
        $client = auth('client')->user();
        $code = trim($request->input('code', ''));

        if (empty($code)) {
            return response()->json(['success' => false, 'message' => 'Veuillez scanner ou saisir un identifiant.'], 400);
        }

        $card = $client->loyaltyCards()
            ->where(function ($q) use ($code) {
                $q->where('card_code', $code)
                    ->orWhere('nfc_uid', $code)
                    ->orWhere('customer_phone', $code);
            })
            ->first();

        if (! $card) {
            return response()->json([
                'success' => false,
                'message' => "Aucune carte trouvée pour '{$code}'.",
            ], 404);
        }

        $settings = $client->getLoyaltyProgramSetting();
        $discountValue = $settings->calculateDiscountForPoints($card->points_balance);

        return response()->json([
            'success' => true,
            'card' => [
                'id' => $card->id,
                'card_code' => $card->card_code,
                'customer_name' => $card->customer_name,
                'customer_phone' => $card->customer_phone,
                'customer_email' => $card->customer_email,
                'card_type' => $card->card_type,
                'nfc_uid' => $card->nfc_uid,
                'points_balance' => $card->points_balance,
                'points_discount_value' => $discountValue,
                'currency' => $settings->currency,
                'stamps_count' => $card->stamps_count,
                'max_stamps' => $card->max_stamps,
                'reward_text' => $card->reward_text,
                'is_reward_available' => $card->isRewardAvailable(),
                'progress_percentage' => $card->progressPercentage(),
                'public_url' => $card->public_url,
            ],
            'settings' => [
                'currency' => $settings->currency,
                'spend_amount_ratio' => $settings->spend_amount_ratio,
                'points_per_ratio' => $settings->points_per_ratio,
                'min_spend_amount' => $settings->min_spend_amount,
                'redemption_points' => $settings->redemption_points,
                'redemption_value' => $settings->redemption_value,
                'services_catalog' => $settings->services_catalog ?? [],
            ],
        ]);
    }

    /**
     * AJAX Endpoint: Process Point additions, reductions, spend calculations, or stamp punch.
     */
    public function processPoints(Request $request): JsonResponse
    {
        $client = auth('client')->user();

        $validated = $request->validate([
            'card_id' => 'required|integer',
            'operation' => 'required|in:add_spend,add_services,add_manual,deduct_points,add_stamp',
            'amount' => 'nullable|numeric|min:0',
            'points' => 'nullable|integer|min:1|max:100000',
            'notes' => 'nullable|string|max:255',
        ]);

        $card = $client->loyaltyCards()->findOrFail($validated['card_id']);
        $settings = $client->getLoyaltyProgramSetting();
        $notes = $validated['notes'] ?? null;
        $message = '';

        switch ($validated['operation']) {
            case 'add_spend':
                $amount = (float) ($validated['amount'] ?? 0);
                $earnedPoints = $settings->calculatePointsForSpend($amount);

                if ($earnedPoints <= 0) {
                    return response()->json([
                        'success' => false,
                        'message' => "Le montant ({$amount} {$settings->currency}) ne permet pas de cumuler de points (Palier: {$settings->spend_amount_ratio} {$settings->currency} = {$settings->points_per_ratio} pt).",
                    ], 422);
                }

                $txNote = "Achat de {$amount} {$settings->currency}".($notes ? " - {$notes}" : '');
                $card->addPoints($earnedPoints, $txNote);
                $message = "+{$earnedPoints} point(s) crédité(s) pour {$amount} {$settings->currency} dépensés !";
                break;

            case 'add_services':
            case 'add_manual':
                $points = (int) $validated['points'];
                $card->addPoints($points, $notes ?: 'Prestations / Ajustement');
                $message = "+{$points} point(s) crédité(s) !";
                break;

            case 'deduct_points':
                $points = (int) $validated['points'];
                if ($card->points_balance < $points) {
                    return response()->json([
                        'success' => false,
                        'message' => "Solde insuffisant : ce client ne dispose que de {$card->points_balance} points.",
                    ], 422);
                }

                $discount = $settings->calculateDiscountForPoints($points);
                $txNote = "Utilisation de {$points} pts (Remise: {$discount} {$settings->currency})".($notes ? " - {$notes}" : '');
                $card->deductPoints($points, $txNote);
                $message = "-{$points} point(s) déduit(s) (Remise accordée : {$discount} {$settings->currency}) !";
                break;

            case 'add_stamp':
                $card->addStamp(1, $notes ?: 'Passage en caisse');
                $message = '+1 tampon validé !';
                break;
        }

        $card->refresh();
        $discountValue = $settings->calculateDiscountForPoints($card->points_balance);

        return response()->json([
            'success' => true,
            'message' => $message,
            'card' => [
                'id' => $card->id,
                'points_balance' => $card->points_balance,
                'points_discount_value' => $discountValue,
                'stamps_count' => $card->stamps_count,
                'max_stamps' => $card->max_stamps,
                'is_reward_available' => $card->isRewardAvailable(),
                'progress_percentage' => $card->progressPercentage(),
            ],
        ]);
    }

    /**
     * Show points calculation rules & settings configuration page.
     */
    public function settings(): View
    {
        $client = auth('client')->user();
        $settings = $client->getLoyaltyProgramSetting();

        return view('client.loyalty.settings', compact('client', 'settings'));
    }

    /**
     * Update points calculation rules & settings.
     */
    public function updateSettings(Request $request): RedirectResponse
    {
        $client = auth('client')->user();

        $validated = $request->validate([
            'points_enabled' => 'nullable|boolean',
            'calculation_mode' => 'required|in:spend_amount,services,both,custom',
            'currency' => 'required|string|max:10',
            'spend_amount_ratio' => 'required|numeric|min:0.01',
            'points_per_ratio' => 'required|integer|min:1|max:1000',
            'min_spend_amount' => 'nullable|numeric|min:0',
            'redemption_points' => 'required|integer|min:1|max:100000',
            'redemption_value' => 'required|numeric|min:0.01',
            'services' => 'nullable|array',
            'services.*.name' => 'nullable|string|max:150',
            'services.*.price' => 'nullable|numeric|min:0',
            'services.*.points' => 'nullable|integer|min:1',
        ]);

        // Clean services catalog array
        $servicesCatalog = [];
        if (! empty($validated['services']) && is_array($validated['services'])) {
            $idCounter = 1;
            foreach ($validated['services'] as $svc) {
                if (! empty($svc['name']) && ! empty($svc['points'])) {
                    $servicesCatalog[] = [
                        'id' => $idCounter++,
                        'name' => trim($svc['name']),
                        'price' => isset($svc['price']) ? (float) $svc['price'] : 0.0,
                        'points' => (int) $svc['points'],
                    ];
                }
            }
        }

        $settings = $client->getLoyaltyProgramSetting();
        $settings->update([
            'points_enabled' => $request->boolean('points_enabled', true),
            'calculation_mode' => $validated['calculation_mode'],
            'currency' => trim($validated['currency']),
            'spend_amount_ratio' => (float) $validated['spend_amount_ratio'],
            'points_per_ratio' => (int) $validated['points_per_ratio'],
            'min_spend_amount' => (float) ($validated['min_spend_amount'] ?? 0),
            'redemption_points' => (int) $validated['redemption_points'],
            'redemption_value' => (float) $validated['redemption_value'],
            'services_catalog' => $servicesCatalog,
        ]);

        return redirect()->route('client.loyalty.settings')->with(
            'success',
            'Règles de calcul des points et paramètres de fidélité mis à jour avec succès !'
        );
    }

    /**
     * Bind a physical NFC tag UID to this loyalty card after browser NFC write
     */
    public function bindNfcUid(Request $request, LoyaltyCard $loyalty): JsonResponse
    {
        $this->authorizeClientAccess($loyalty);

        $validated = $request->validate([
            'nfc_uid' => 'required|string|max:100',
        ]);

        $loyalty->update([
            'nfc_uid' => trim($validated['nfc_uid']),
            'card_type' => $loyalty->card_type === 'qr_code' ? 'both' : $loyalty->card_type,
        ]);

        return response()->json([
            'success' => true,
            'message' => "UID NFC {$loyalty->nfc_uid} associé avec succès à la carte de {$loyalty->customer_name} !",
            'nfc_uid' => $loyalty->nfc_uid,
        ]);
    }

    /**
     * Strict tenant ownership validation.
     */
    protected function authorizeClientAccess(LoyaltyCard $card): void
    {
        $client = auth('client')->user();
        if ($card->client_id !== $client->id) {
            abort(403, 'Accès non autorisé à cette carte de fidélité.');
        }
    }
}
